[{"order":1,"type":"heading","text":"Dependency Injection in PHP: A Comprehensive Guide"},{"order":2,"type":"subheading","text":"Introduction to Dependency Injection"},{"order":3,"type":"paragraph","text":"Dependency Injection (DI) is a design pattern that promotes loose coupling between classes. Instead of a class creating its dependencies, they are 'injected' into the class from an external source. This makes code more testable, maintainable, and reusable."},{"order":4,"type":"paragraph","text":"In essence, DI is about providing the dependencies a class needs, rather than the class creating them itself. This is achieved through constructor injection, setter injection, or interface injection."},{"order":5,"type":"subheading","text":"Types of Dependency Injection"},{"order":6,"type":"bullet_point","text":"Constructor Injection: Dependencies are passed through the class constructor."},{"order":7,"type":"bullet_point","text":"Setter Injection: Dependencies are injected via setter methods."},{"order":8,"type":"bullet_point","text":"Interface Injection: Dependencies are injected through an interface."},{"order":9,"type":"subheading","text":"Constructor Injection Example"},{"order":10,"type":"paragraph","text":"This is the most common and recommended type of DI. The dependencies are passed as arguments to the class's constructor."},{"order":11,"type":"code","text":"// Interface for a Logger
interface LoggerInterface {
    public function log(string $message);
}

// Concrete Logger implementation
class FileLogger implements LoggerInterface {
    private $filePath;

    public function __construct(string $filePath) {
        $this->filePath = $filePath;
    }

    public function log(string $message) {
        file_put_contents($this->filePath, $message . "\n", FILE_APPEND);
    }
}

// Class that depends on a Logger
class UserProfile {
    private $logger;

    public function __construct(LoggerInterface $logger) {
        $this->logger = $logger;
    }

    public function createUser(string $username) {
        // Create user logic here...
        $this->logger->log("User created: " . $username);
    }
}

// Usage with Dependency Injection
$logger = new FileLogger('log.txt');
$userProfile = new UserProfile($logger);
$userProfile->createUser('john.doe');"},{"order":12,"type":"subheading","text":"Setter Injection Example"},{"order":13,"type":"paragraph","text":"Dependencies are injected using setter methods. This is useful when a dependency is optional."},{"order":14,"type":"code","text":"class DatabaseConnection {
    private $host;
    private $username;
    private $password;

    public function connect(string $host, string $username, string $password) {
        $this->host = $host;
        $this->username = $username;
        $this->password = $password;
        // Connection logic here...
    }
}

class UserRepository {
    private $dbConnection;

    public function setDatabaseConnection(DatabaseConnection $dbConnection) {
        $this->dbConnection = $dbConnection;
    }

    public function getUser(int $id) {
        // Use $this->dbConnection to fetch user from the database
    }
}

// Usage with Setter Injection
$dbConnection = new DatabaseConnection();
$dbConnection->connect('localhost', 'user', 'password');

$userRepository = new UserRepository();
$userRepository->setDatabaseConnection($dbConnection);"},{"order":15,"type":"subheading","text":"Interface Injection Example"},{"order":16,"type":"paragraph","text":"Dependencies are injected through an interface. This is less common but can be useful in specific scenarios."},{"order":17,"type":"code","text":"interface Injectable {
    public function setDependency(Dependency $dependency);
}

class Dependency {
    // ...
}

class Client implements Injectable {
    private $dependency;

    public function setDependency(Dependency $dependency) {
        $this->dependency = $dependency;
    }

    public function doSomething() {
        // Use $this->dependency
    }
}

// Usage with Interface Injection
$dependency = new Dependency();
$client = new Client();
$client->setDependency($dependency);"},{"order":18,"type":"subheading","text":"Dependency Injection Containers"},{"order":19,"type":"paragraph","text":"A Dependency Injection Container (also known as an IoC Container) is a framework that manages the creation and injection of dependencies. It automates the process, making it easier to manage complex dependencies."},{"order":20,"type":"paragraph","text":"Popular PHP DI Containers include Symfony DI Container, Laravel Service Container, and PHP-DI."},{"order":21,"type":"subheading","text":"Benefits of Dependency Injection"},{"order":22,"type":"bullet_point","text":"Increased Testability: Easier to mock dependencies for unit testing."},{"order":23,"type":"bullet_point","text":"Reduced Coupling: Classes are less dependent on concrete implementations."},{"order":24,"type":"bullet_point","text":"Improved Reusability: Classes can be easily reused in different contexts."},{"order":25,"type":"bullet_point","text":"Enhanced Maintainability: Changes in one class are less likely to affect other classes."},{"order":26,"type":"subheading","text":"Conclusion"},{"order":27,"type":"paragraph","text":"Dependency Injection is a powerful design pattern that can significantly improve the quality of your PHP code. By embracing DI, you can create more testable, maintainable, and reusable applications."}]
